// === Tab: mySketch.js ===
let vmin, vmax;
let tex, texSize = 512;
let gl, glsl;
let mx, my, me = 0.015;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1352844/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
  gl = drawingContext;
  vmin = (width < height) ? width : height;
  vmax = (width > height) ? width : height;
  mx = width / 2;
  my = height / 2;
  tex = createGraphics(texSize, texSize);
}

function container(size) {
  let s = size * sqrt(2);
  let r = s / 2;
  let h = size;
  push();
  {
    rotateX(-PI / 2);
    rotateY(PI / 4);
    cylinder(r, h, 5, 1, false);
  }
  pop();
}

function outsideBox(size) {
  gl.colorMask(false, false, false, false);
  container(size);
}

function insideBox(size) {
  gl.colorMask(true, true, true, true);
  gl.enable(gl.CULL_FACE);
  gl.cullFace(gl.BACK);
  container(size);
  gl.disable(gl.CULL_FACE);
}

function portalBox(size) {
  outsideBox(size + 1);
  insideBox(size);
}

function portal(size, sec) {
  portalBox(size);

  push();
  {
    rotateY(sec * -0.5);
    push();
    {
      rotateX(PI * 0.25);
      rotateY(PI * 0.25);
      sphere(size * 0.3);
    }
    pop();
  }
  pop();
}

function draw() {
  let sec = millis() / 1000;
  let size = vmin / 2;
  mx += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mx) * me;
  my += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) * me;
  let rx = PI * map(my, 0, height, -0.5, 0.5);
  let ry = PI * map(mx, 0, width, 0.5, -0.5);

  background(30);

  rotateX(rx);
  rotateY(ry);

  noStroke();

  shader(glsl);

  push();
  {
    translate(0, 0, -size);
    portal(size, sec);
  }
  pop();

  push();
  {
    translate(0, size, 0);
    rotateX(PI * 0.5);

    portal(size, sec);
  }
  pop();
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

